            Choice("中继计划换位位置").Select(request.Destination is{} destination?destination+1:0);var deviceItems=battle.Traps.Where(t=>t.Owner==actor.Id).Select(t=>t.Id).Concat(battle.Supplies.Where(s=>!s.Used).Select(s=>s.Instance)).ToArray();int device=request.Device is null?-1:Array.IndexOf(deviceItems,request.Device);if(request.Device is not null&&device<0)throw new InvalidOperationException("Engineering controller chose an absent actual relay device.");Choice("中继装置或入口补给").Select(device+1);
