            await Spot("R0-S05.relay_note");await Click("取得中继防卫完整说明");var source=_campaignApproaches.Package.Materials.Single(m=>m.Id=="R0-APP-R-RELAY");Check("relay_full_original_actually_displayed",Nodes(_panels.Peek().Panel).OfType<TextEdit>().Any(t=>!t.Editable&&t.Text==string.Join("\n\n",source.Paragraphs.Select(p=>p.En))));ApplyFontScale(200);await Frame();Check("relay_reader_200_percent",_split.Vertical&&Nodes(_panels.Peek().Panel).OfType<TextEdit>().Single().GetThemeFontSize("font_size")==44);ApplyFontScale(100);await RejectWrongStation();CloseAll();
            await Spot("R0-S05.relay");await Click("中继检修边界 · 明确处置或继续");Check("relay_supplies_not_implicitly_carried",Nodes(_panels.Peek().Panel).OfType<CheckBox>().All(c=>!c.ButtonPressed));await Click("明确进入中继防卫");var entry=(await _campaignApproaches.EncounterAsync(FirstApproachRules.Relay))!;Check("relay_actual_panel_current_hero_only_and_movement_blocked",CampaignApproachSelected&&CampaignApproachBlocksMovement&&!MayMove()&&entry.Battle.Units.Count(u=>u.Side==CombatSide.Ally)==1&&entry.Battle.Units.Single(u=>u.Side==CombatSide.Ally).Id=="hero"&&Nodes(_panels.Peek().Panel).OfType<OptionButton>().Any(o=>o.AccessibilityName=="中继计划行动"));
            await SelectAction();var token=_campaignApproachTokens.Single();long sequence=(await _store.SnapshotAsync()).Sequence;await Click("返回");Check("relay_closed_preview_cannot_execute_or_write",(await _campaignApproaches.ConfirmAsync(token)).Status==CommitStatus.Rejected&&(await _store.SnapshotAsync()).Sequence==sequence);
