            await Click("撤回完整中继入口…");await Click("明确撤回此次中继入口");Check("relay_withdraw_restores_original_entry_and_retains_source",(await _campaignApproaches.EncounterAsync(FirstApproachRules.Relay))!.Battle.Outcome==CombatOutcome.Withdrawn&&(await _campaignApproaches.MaterialsAsync()).Length==1&&!CampaignApproachBlocksMovement);await Spot("R0-S05.relay");await Click("中继检修边界 · 明确处置或继续");await Click("明确进入中继防卫");var retry=(await _campaignApproaches.EncounterAsync(FirstApproachRules.Relay))!;Check("relay_retry_same_instance_new_attempt",retry.Battle.Instance==entry.Battle.Instance&&retry.Battle.Attempt!=entry.Battle.Attempt);
            for(int i=0;i<600&&(await _campaignApproaches.EncounterAsync(FirstApproachRules.Relay))!.Battle.Outcome==CombatOutcome.Active;i++){await SelectAction();await Click("明确执行所选中继行动");}
            var result=await _store.SnapshotAsync();Check("relay_actual_control_single_result_without_reward_or_auto_repair",FirstApproachService.RelayCleared(result)&&result.Receipts.Count(r=>r.SemanticKey=="first-approach:ENC-R0-02:result")==1&&result.Balances.OrderBy(p=>p.Key).SequenceEqual(start.Balances.OrderBy(p=>p.Key))&&!(await _service.ViewAsync()).Prologue.RelayReady);CloseAll();await Spot("R0-S05.relay");await Click("关闭并隔离中继设备");await Spot("R0-S05.relay");await Click("在隔离状态接好中继引线");var final=await _service.ViewAsync();Check("actual_ui_relay_seat_after_control_does_not_auto_power_test_or_collect",final.Prologue.RelayLeadSeated&&!final.Prologue.RelayReady&&!final.Prologue.RecorderCollected&&!final.Prologue.MailbagCollected&&final.Snapshot.Balances["experience"]==140);CloseAll();await _store.CreateCheckpointAsync("manual");
        }
        catch(Exception error){failures++;checks.Add(new{name="relay_native_exception",passed=false,error=error.ToString()});}
        CloseAll();await Frame();string output=System.Environment.GetEnvironmentVariable("MISTSEA_CLIENT_TEST_OUTPUT")??ProjectSettings.GlobalizePath("user://client-test");Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"first_relay_client_results.json"),StrictJson.Serialize(new{checks,failures,source="actual zero-XP to 140XP normal-first-relay-native-entry; native full source, begin/action/preview/cancel/continue/withdraw/retry and real repair buttons; action choices supplied by engineering controller",human_native_play="not_run",physical_ime="not_run",screen_reader="not_run",balance_and_language_calibration="human_pending"}));GD.Print("MISTSEA_FIRST_RELAY_CLIENT_TESTS "+checks.Count+" failures="+failures);GetTree().Quit(failures==0?0:1);
    }
